 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.tool.name,style:const TextStyle(fontWeight:FontWeight.w900))),body:ListView(padding:const EdgeInsets.all(18),children:[Text(widget.tool.description,style:const TextStyle(color:Color(0xFF52606D))),const SizedBox(height:22),for(var i=0;i<labels.length;i++)if(labels[i].isNotEmpty)Padding(padding:const EdgeInsets.only(bottom:14),child:TextField(controller:controllers[i],keyboardType:TextInputType.text,decoration:InputDecoration(labelText:labels[i],filled:true,border:const OutlineInputBorder(borderSide:BorderSide.none)))),FilledButton(onPressed:calculate,child:const Text('Calcular')),const SizedBox(height:18),Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:const Color(0xFFE7F8F2),borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Resultado',style:TextStyle(fontWeight:FontWeight.w800)),Text('${result.toStringAsFixed(2).replaceAll('.',',')} $unit',style:const TextStyle(fontSize:34,fontWeight:FontWeight.w900))]))]));
}
